  Int   residue;                   // for rounding
  Int   reqdigits=set->digits;     // requested DIGITS
  Int   exponent;                  // working exponent
  Int   maxexponent=0;             // DIVIDE maximum exponent if unrounded
  uByte bits;                      // working sign
  Unit  *target;                   // work
