#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "jv.h"

int LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
  // Creat null-terminated string
  char *null_terminated = (char *)malloc(size + 1);
  memcpy(null_terminated, (char *)data, size);
  null_terminated[size] = '\0';

  // Fuzzer entrypoint
  jv res = jv_parse(null_terminated);
  jv_free(res);

  // Free the null-terminated string
  free(null_terminated);

  return 0;
}
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#include "jq.h"

int LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
  // Creat null-terminated string
  char *null_terminated = (char *)malloc(size + 1);
  memcpy(null_terminated, (char *)data, size);
  null_terminated[size] = '\0';

  // Fuzzer entrypoint
  jq_state *jq = NULL;
  jq = jq_init();
  if (jq != NULL) {
    jq_compile(jq, null_terminated);
  }
  jq_teardown(&jq);

  // Free the null-terminated string
  free(null_terminated);

  return 0;
}
#include <stdint.h>
#include <stdlib.h>

#include "jv.h"

int LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
  // Create file with fuzzer data
  char filename[256];
  sprintf(filename, "/tmp/libfuzzer.%d", getpid());
  FILE *fp = fopen(filename, "wb");
  if (!fp) {
    return 0;
  }
  fwrite(data, size, 1, fp);
  fclose(fp);

  // Fuzz the two version of jv_load_file
  jv data1 = jv_load_file(filename, 1);
  jv_free(data1);
  jv data2 = jv_load_file(filename, 0);
  jv_free(data2);

  // Clean up fuzz file
  unlink(filename);

  return 0;
}
